import unittest
from tail import tail
from fakefile import FakeFile


class Regression(unittest.TestCase):
    def test_fewer_lines_than_n(self):
        self.assertEqual(tail(FakeFile(["a\n", "b\n"]), 5), ["a\n", "b\n"])

    def test_zero_lines(self):
        self.assertEqual(tail(FakeFile(["a\n", "b\n"]), 0), [])

    def test_exact(self):
        self.assertEqual(tail(FakeFile(["a\n", "b\n"]), 2), ["a\n", "b\n"])

    def test_empty_file(self):
        self.assertEqual(tail(FakeFile([]), 3), [])

